import { Tool } from '../../Tool.js';
import { z } from 'zod';
import { formatTextContents } from '../../utils/content.js';
import { getToolErrorMessage } from '../../utils/errors.js';
import { absoluteCurrentWorkingDirectory, absoluteProjectPath, account, } from './constants.js';
import { setupHubSpotConfig } from '../../utils/config.js';
import { resolveAccountId } from './resolveAccount.js';
import { getApps } from './apps.js';
const inputSchema = {
    absoluteCurrentWorkingDirectory,
    absoluteProjectPath: absoluteProjectPath.optional(),
    account,
};
// eslint-disable-next-line @typescript-eslint/no-unused-vars
const inputSchemaZodObject = z.object({ ...inputSchema });
const toolName = 'get-apps-info';
export class GetApplicationInfoTool extends Tool {
    constructor(mcpServer, logger) {
        super(mcpServer, logger, toolName);
    }
    async handler({ account, absoluteCurrentWorkingDirectory, absoluteProjectPath, }) {
        setupHubSpotConfig(absoluteProjectPath ?? absoluteCurrentWorkingDirectory);
        try {
            const resolved = await resolveAccountId(this.mcpServer, this.logger, {
                toolName,
                account,
            });
            if ('response' in resolved) {
                return resolved.response;
            }
            const { accountId } = resolved;
            const data = await getApps(accountId);
            const formattedResult = JSON.stringify(data, null, 2);
            return formatTextContents(formattedResult);
        }
        catch (error) {
            this.logger.debug(toolName, {
                message: 'Handler caught error',
                error: error instanceof Error ? error.message : String(error),
            });
            return formatTextContents(getToolErrorMessage(error));
        }
    }
    register() {
        return this.mcpServer.registerTool(toolName, {
            title: 'Get Apps Information',
            description: 'Retrieves a list of all HubSpot apps available in the current account. Returns an array of apps, where each app contains an appId (numeric identifier) and appName (string). This information is useful for identifying available apps before using other tools that require specific app IDs, such as getting API usage patterns. No input parameters are required - this tool fetches all apps from the HubSpot Insights API.',
            inputSchema,
            annotations: {
                readOnlyHint: true,
                openWorldHint: true,
            },
        }, (input, extra) => this.wrappedHandler(input, extra));
    }
}
